import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.Dd_iHz3e.js";const g=JSON.parse('{"title":"Step 12: Technical Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"11-glossary.md","filePath":"11-glossary.md"}'),o={name:"11-glossary.md"};function n(s,e,l,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="step-12-technical-glossary" tabindex="-1">Step 12: Technical Glossary <a class="header-anchor" href="#step-12-technical-glossary" aria-label="Permalink to &quot;Step 12: Technical Glossary&quot;">​</a></h1><p>This glossary defines all key technical terms, protocols, and architectural concepts used throughout the Cooking Nexus platform.</p><hr><h3 id="a" tabindex="-1">A <a class="header-anchor" href="#a" aria-label="Permalink to &quot;A&quot;">​</a></h3><ul><li><strong>Adaptive Bitrate Streaming (ABR)</strong>: A technique used in video delivery (such as HLS or DASH) where video quality adjusts dynamically based on the client&#39;s network bandwidth.</li><li><strong>Atomic Operation</strong>: A database write or modification that completes entirely or fails entirely, preventing race conditions during concurrent updates.</li></ul><h3 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h3><ul><li><strong>BSON (Binary JSON)</strong>: The binary-encoded serialization format used by MongoDB to store documents, supporting rich data types like Date and 64-bit integers.</li></ul><h3 id="c" tabindex="-1">C <a class="header-anchor" href="#c" aria-label="Permalink to &quot;C&quot;">​</a></h3><ul><li><strong>Change Data Capture (CDC)</strong>: A software pattern that monitors database transaction logs (such as the MongoDB Oplog) to stream real-time change events into downstream systems like Kafka or Elasticsearch.</li><li><strong>Concurrent Mode</strong>: A set of features in React 18 enabling interruptible rendering, allowing background UI updates without freezing active user interactions.</li></ul><h3 id="d" tabindex="-1">D <a class="header-anchor" href="#d" aria-label="Permalink to &quot;D&quot;">​</a></h3><ul><li><strong>Deno</strong>: A secure, modern JavaScript/TypeScript runtime built on the V8 engine and Rust, used for executing Supabase Edge Functions.</li></ul><h3 id="g" tabindex="-1">G <a class="header-anchor" href="#g" aria-label="Permalink to &quot;G&quot;">​</a></h3><ul><li><strong>GATT (Generic Attribute Profile)</strong>: The Bluetooth Low Energy protocol defining how connected peripherals (like the Bluetooth Kitchen Scale in <code>092-IoT-Scale-Sync</code>) expose hierarchical services and characteristics.</li></ul><h3 id="j" tabindex="-1">J <a class="header-anchor" href="#j" aria-label="Permalink to &quot;J&quot;">​</a></h3><ul><li><strong>JWT (JSON Web Token)</strong>: An open standard (RFC 7519) compact URL-safe format used for digitally signing claims (such as email identity and expiration) using an HMAC-SHA256 secret.</li></ul><h3 id="m" tabindex="-1">M <a class="header-anchor" href="#m" aria-label="Permalink to &quot;M&quot;">​</a></h3><ul><li><strong>Magic Link</strong>: A passwordless authentication mechanism where the server sends a single-use, time-limited cryptographic token via email or link, verifying identity upon retrieval.</li><li><strong>Mongoose</strong>: An Object Data Modeling (ODM) library for MongoDB and Node.js that provides schema enforcement, type casting, validation, and query middleware.</li></ul><h3 id="o" tabindex="-1">O <a class="header-anchor" href="#o" aria-label="Permalink to &quot;O&quot;">​</a></h3><ul><li><strong>Oplog (Operations Log)</strong>: A capped collection in MongoDB that records a rolling history of all data modifications, enabling replica set synchronization and CDC pipelines.</li><li><strong>Optimistic UI</strong>: A frontend state pattern where the UI updates immediately upon user interaction (such as incrementing a like counter) before waiting for server confirmation.</li></ul><h3 id="r" tabindex="-1">R <a class="header-anchor" href="#r" aria-label="Permalink to &quot;R&quot;">​</a></h3><ul><li><strong>Radix UI</strong>: A collection of unstyled, headless, accessible component primitives (Dialog, DropdownMenu, Tabs) that comply with WAI-ARIA standards.</li></ul><h3 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h3><ul><li><strong>Server-Sent Events (SSE)</strong>: A unidirectional HTTP streaming protocol (<code>text/event-stream</code>) allowing a server to push real-time text events to a browser over a single persistent connection.</li><li><strong>Structured Outputs</strong>: A technique in LLM engineering where a language model is constrained via strict grammar or system instructions to output only valid, parseable JSON matching a defined schema.</li></ul><h3 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h3><ul><li><strong>Time to First Token (TTFT)</strong>: The latency duration measured from when an HTTP request is dispatched to an AI model until the first token chunk arrives at the client reader.</li><li><strong>Token Bucket Algorithm</strong>: A rate limiting algorithm where tokens accumulate at a constant fill rate up to a bucket capacity, preventing traffic bursts from overwhelming downstream APIs.</li></ul><h3 id="v" tabindex="-1">V <a class="header-anchor" href="#v" aria-label="Permalink to &quot;V&quot;">​</a></h3><ul><li><strong>VitePress</strong>: A static site generator built on top of Vite and Vue, designed for authoring fast, lightweight developer documentation sites.</li></ul>',27)])])}const m=t(o,[["render",n]]);export{g as __pageData,m as default};
